using System.Collections;
using Astrea.BattleActions;
using DG.Tweening;
using LittleLeo;
using NaughtyAttributes;
using Spine.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class CompanionSpriteControl : SpriteControl
{
	[Header("Companion Components")]
	[SerializeField]
	private bool companionForBattle;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionCorruptionStats companionCorruptionStats;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionAbility companionAbility;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionEffects companionEffects;

	[SerializeField]
	[HideIf("companionForBattle")]
	private SkeletonGraphic skeletonGraphicForReward;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject corruptionGaugeLevelAndEffects;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionInitializer companionInitializer;

	[Header("Corrupted Animation")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private float corruptShakeDuration;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private float corruptShakeAmount;

	[Header("Defeated Animation")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private float shakeDuration;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private float shakeAmount;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private AnimationCurve shakeCurve;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject sentinelBreakVFXPrefab;

	[Header("Companion Assets")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private CurrentCompanions currentCompanions;

	[Header("Compendium")]
	[SerializeField]
	private bool compendium;

	[Header("Companion Reward")]
	[SerializeField]
	private Vector3 defaultCompanionRewardSkeletonAnimationPosition;

	[Header("Mods")]
	[SerializeField]
	[HideIf("companionForBattle")]
	private GameObject moddedCompanionImageForRewardPrefab;

	[SerializeField]
	[HideIf("companionForBattle")]
	private Transform skeletonGraphicPivot;

	[SerializeField]
	[HideIf("companionForBattle")]
	private CompanionRewardInstance companionRewardInstance;

	private Image moddedImage;

	private bool defeatedByScrapping;

	private CompanionScrappingAction companionScrappingAction;

	private CompanionData companionData;

	private SpriteRenderer brokenCompanionSmokeSprite;

	private ParticleEmissionController particleEmissionControllerSentinelBrokenVFX;

	public SkeletonGraphic SkeletonGraphicForReward => skeletonGraphicForReward;

	private CompanionSFXData companionSFXData => companionInitializer.CompanionSFXData;

	public void Initialize(CompanionData companionData)
	{
		this.companionData = companionData;
		animationData = companionData.AnimationData;
		if (companionData.EnableUnitsMiscData)
		{
			enableUnitsMiscData = true;
			unitsMiscData = companionData.UnitsMiscData;
		}
		else
		{
			enableUnitsMiscData = false;
			unitsMiscData = null;
		}
		if (companionForBattle)
		{
			SpawnSkeletonAnimation();
			ResetOutlineBrightness();
		}
		else
		{
			InitializeCompanionForReward();
		}
	}

	protected override void SpawnSkeletonAnimation()
	{
		base.SpawnSkeletonAnimation();
		skeletonTransform.position = base.transform.position;
		brokenCompanionSmokeSprite = skeletonTransform.GetChild(3).GetComponent<SpriteRenderer>();
		brokenCompanionSmokeSprite.gameObject.SetActive(value: false);
		particleEmissionControllerSentinelBrokenVFX = skeletonTransform.GetChild(4).GetComponent<ParticleEmissionController>();
		particleEmissionControllerSentinelBrokenVFX.SetActiveEmissionModule(value: false);
		InitializeSkeletonAndLight();
	}

	public void InitializeSkeletonAndLight()
	{
		companionCorruptionStats.ToggleAliveAndFaintedCompanion(value: true);
		PlayAnimationForcedCoroutine(ReferenceSingleton<CoroutineHandler>.Instance, AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
		lightSprite.material.SetFloat("_TextTween", 0f);
		FadeBrokenCompanionSmokeSprite(value: false, 0.4f);
		particleEmissionControllerSentinelBrokenVFX.SetActiveEmissionModule(value: false);
		CheckRestartModdedSpriteDoTweenFloatingAnimation();
	}

	private void CheckRestartModdedSpriteDoTweenFloatingAnimation()
	{
		if (animationData.Modded)
		{
			moddedSpriteRenderer.GetComponent<DOTweenAnimation>().DORestart();
		}
	}

	private void FadeBrokenCompanionSmokeSprite(bool value, float duration)
	{
		if (value)
		{
			brokenCompanionSmokeSprite.gameObject.SetActive(value: true);
		}
		ReferenceSingleton<CoroutineHandler>.Instance.Run(brokenCompanionSmokeSprite.FadeSprite(value ? 1 : 0, duration, shakeCurve, delegate
		{
			if (!value)
			{
				brokenCompanionSmokeSprite.gameObject.SetActive(value: false);
			}
		}));
	}

	public void InitializeRepairBrokenCompanion()
	{
		InitializeSkeletonAndLight();
		SetMixDuration(1.5f);
		InitializeMaterialProperties();
	}

	public void EndOfBattleInitializeBrokenCompanion()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionSFXData.Repairing);
		InitializeSkeletonAndLight();
	}

	public override void OnReceivePurify()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionSFXData.ReceivingPurify);
		base.OnReceivePurify();
	}

	public override void OnReceiveCorruption()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionSFXData.ReceivingCorruption);
		base.OnReceiveCorruption();
		ReceiveCorruptionShake();
	}

	private void ReceiveCorruptionShake()
	{
		CoroutineUtility.ShakeRoutine(ReferenceSingleton<CoroutineHandler>.Instance, animationSkeleton.transform, corruptShakeDuration, corruptShakeAmount);
	}

	public override void OnReceiveFatalDamage()
	{
		PlayVisualEffect(VisualEffectType.Corrupt);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatAnimationCoroutines(OnReceiveFatalDamageCoroutine());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		companionEffects.ActivateAreaPurifyCorruptOnBreakEffects(recycle: false);
		CompanionCompletelyCorrupted();
	}

	private IEnumerator OnReceiveFatalDamageCoroutine()
	{
		Debug.Log("CompanionSpriteControl: OnReceiveFatalDamageCoroutine");
		yield return InvokeAlternatives.WaitForFrames(5);
		yield return new WaitUntil(() => !companionAbility.PlayActivationAnimationEnqueued);
		Debug.Log("CompanionSpriteControl: OnReceiveFatalDamageCoroutine2");
		CoroutineUtility.ShakeRoutine(ReferenceSingleton<CoroutineHandler>.Instance, animationSkeleton.transform, shakeDuration, shakeAmount, shakeCurve);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(lightSprite.material.TweenFloatProperty("_TextTween", 1f, shakeDuration, shakeCurve));
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionSFXData.Breaking);
		if (defeatedByScrapping)
		{
			companionScrappingAction.SpawnScrappingVFX(base.gameObject);
		}
		ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(sentinelBreakVFXPrefab, base.transform.position, 4f);
		corruptionGaugeLevelAndEffects.SetActive(value: false);
		companionAbility.StoreDice();
		companionCorruptionStats.DisableAliveCompanion(playerCompletelyCorrupted: false);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, shakeDuration - 0.6f, delegate
		{
			FadeBrokenCompanionSmokeSprite(value: true, 0.9f);
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				particleEmissionControllerSentinelBrokenVFX.SetActiveEmissionModule(value: true);
			}
		});
		yield return new WaitForSeconds(shakeDuration);
		PlayAnimationForcedCoroutine(ReferenceSingleton<CoroutineHandler>.Instance, AnimationType.Die, AnimationChangeType.StayInTheNewAnimationNotLooping);
		SetMixDuration(0f);
		if (animationData.Modded)
		{
			moddedSpriteRenderer.GetComponent<DOTweenAnimation>().DORewind();
		}
		yield return InvokeAlternatives.WaitForFrames(3);
		defeatedByScrapping = false;
		companionCorruptionStats.ResetCompletelyCorrupted();
		companionEffects.RemoveAllEffectsWithCallbacks();
		companionInitializer.SentinelAutoRepairHUD.ShowSentinelAutoRepairHUD();
	}

	private void CompanionCompletelyCorrupted()
	{
		currentCompanions.ActiveCompanions.Remove(base.gameObject);
		currentCompanions.DecayedCompanions.Add(base.gameObject);
		ReferenceSingleton<HeveliusOmensHandler>.Instance.ActivateEnergyAbsorberOmen();
	}

	public void PlayReceiveFatalDamage()
	{
		PlayVisualEffect(VisualEffectType.Corrupt);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(OnReceiveFatalDamageCoroutine());
	}

	public void PlayReceiveFatalDamageInstantlyDefeatCompanionScrapping(CompanionScrappingAction companionScrappingAction)
	{
		defeatedByScrapping = true;
		this.companionScrappingAction = companionScrappingAction;
		OnReceiveFatalDamage();
	}

	private void InitializeCompanionForReward()
	{
		if (!animationData.Modded)
		{
			skeletonGraphicForReward.skeletonDataAsset = animationData.SkeletonDataAsset;
			if (animationData.EnableCustomStartingAnimation)
			{
				skeletonGraphicForReward.startingAnimation = animationData.GetCustomStartingAnimationName(base.gameObject);
			}
			else
			{
				skeletonGraphicForReward.startingAnimation = "Idle";
			}
			skeletonGraphicForReward.Initialize(overwrite: true);
		}
		else
		{
			CheckSpawnModdedImagePrefab();
			moddedImage.sprite = animationData.GetModdedSpriteByType(AnimationType.Idle);
		}
		if (moddedImage != null)
		{
			moddedImage.gameObject.SetActive(animationData.Modded);
		}
		skeletonGraphicForReward.gameObject.SetActive(!animationData.Modded);
		if (compendium)
		{
			if (animationData.Modded)
			{
				moddedImage.material = Object.Instantiate(skeletonGraphicForReward.material);
				moddedImage.material.SetMaterialColor((companionData.CompendiumItemState == CompendiumItemState.Undiscovered) ? Color.black : Color.white);
			}
			else
			{
				skeletonGraphicForReward.material = Object.Instantiate(skeletonGraphicForReward.material);
				skeletonGraphicForReward.material.SetMaterialColor((companionData.CompendiumItemState == CompendiumItemState.Undiscovered) ? Color.black : Color.white);
			}
		}
		CheckCompanionRewardUnitsMiscData();
	}

	private void CheckSpawnModdedImagePrefab()
	{
		if (moddedImage == null)
		{
			moddedImage = Object.Instantiate(moddedCompanionImageForRewardPrefab, skeletonGraphicPivot).GetComponent<Image>();
			companionRewardInstance.SetModdedImage(moddedImage.gameObject);
		}
	}

	private void CheckCompanionRewardUnitsMiscData()
	{
		if (enableUnitsMiscData)
		{
			if (unitsMiscData.EnableCustomCompanionRewardSpinePosition)
			{
				skeletonGraphicForReward.transform.localPosition = unitsMiscData.CustomCompanionRewardSpineGameObjectPosition;
			}
			else
			{
				skeletonGraphicForReward.transform.localPosition = defaultCompanionRewardSkeletonAnimationPosition;
			}
			float num = Mathf.Abs(skeletonGraphicForReward.transform.localScale.x);
			skeletonGraphicForReward.transform.SetLocalScaleX(unitsMiscData.FlipXRewardSpineGameObject ? (0f - num) : num);
		}
		else
		{
			skeletonGraphicForReward.transform.localPosition = defaultCompanionRewardSkeletonAnimationPosition;
		}
	}
}
